89	    constructor(
90	        IERC20 asset_,
91	        address initialOwner,
92	        address initialGuardian,
93	        FeeController feeController_,
94	        uint64 cooldown_
95	    ) Ownable2Step(initialOwner) {
96	        require(address(asset_) != address(0), "ASSET_ZERO");
97	        require(address(feeController_) != address(0), "FEES_ZERO");
98	        asset = asset_;
99	        feeController = feeController_;
100	        guardian = initialGuardian;
101	        withdrawalQueue = new WithdrawalQueue(address(this), cooldown_);
102	    }
103	
104	    // ---------------------------------------------------------------- views
105	
106	    /// @notice Shares that `assets` would mint at the current exchange rate.
107	    function convertToShares(uint256 assets) public view returns (uint256) {
108	        uint256 supply = totalSupply;
109	        if (supply == 0) return assets;
110	        return assets.mulDiv(supply, totalAssets);
111	    }
112	
113	    /// @notice Assets that `shares` are currently worth.
114	    function convertToAssets(uint256 shares) public view returns (uint256) {
115	        uint256 supply = totalSupply;
116	        if (supply == 0) return shares;
117	        return shares.mulDiv(totalAssets, supply);
118	    }
119	
120	    // ------------------------------------------------------------ user flow
121	
122	    /// @notice Stake `assets` and receive shares.
123	    /// @dev Rounds shares down, which favours the vault over the depositor.
124	    function deposit(uint256 assets) external nonReentrant whenNotPaused returns (uint256 shares) {
125	        if (assets == 0) revert ZeroAmount();
126	
127	        _checkpoint(msg.sender);
128	
129	        shares = convertToShares(assets);
130	        if (shares == 0) revert ZeroShares();
131	
132	        totalAssets += assets;
133	        totalSupply += shares;
134	        balanceOf[msg.sender] += shares;
135	
136	        asset.safeTransferFrom(msg.sender, address(this), assets);
137	
138	        emit Deposited(msg.sender, assets, shares);
139	    }
140	
141	    /// @notice Burn `shares` and open a cooldown before the assets can be taken.
142	    /// @dev Deliberately callable while paused so a pause cannot trap funds.
143	    function requestWithdrawal(uint256 shares) external nonReentrant returns (uint256 id) {
144	        if (shares == 0) revert ZeroAmount();
145	
146	        uint256 held = balanceOf[msg.sender];
147	        if (held < shares) revert InsufficientShares(held, shares);
148	
149	        _checkpoint(msg.sender);
150	
151	        uint256 assets = convertToAssets(shares);
152	
153	        balanceOf[msg.sender] = held - shares;
154	        totalSupply -= shares;
155	        totalAssets -= assets;
156	
157	        // The fee in force now is held for this request, so a later fee change
158	        // cannot be applied retroactively to an exit already in the cooldown.
159	        id = withdrawalQueue.enqueue(msg.sender, assets, feeController.withdrawalFeeBps());
160	
161	        emit WithdrawalRequested(msg.sender, id, shares, assets);
162	    }
