165	    /// @dev The fee applied is the one quoted when the request was made.
166	    function completeWithdrawal(uint256 id) external nonReentrant returns (uint256 paid) {
167	        (uint256 assets, uint256 feeBps) = withdrawalQueue.settle(id, msg.sender);
168	
169	        uint256 fee = assets.mulDiv(feeBps, feeController.BPS_DENOMINATOR());
170	        paid = assets - fee;
171	
172	        if (fee != 0) {
173	            asset.safeTransfer(feeController.feeRecipient(), fee);
174	        }
175	        asset.safeTransfer(msg.sender, paid);
176	
