1	// SPDX-License-Identifier: MIT
2	pragma solidity 0.8.24;
3	
4	import {Ownable2Step} from "../auth/Ownable2Step.sol";
5	
6	/// @title FeeController
7	/// @notice Holds the withdrawal fee parameters shared by the vault.
8	/// @dev Split out from the vault so fee policy can be reviewed and changed
9	///      without touching share accounting.
10	///
11	///      Invariants:
12	///        - withdrawalFeeBps <= MAX_FEE_BPS at all times.
13	///        - feeRecipient is never the zero address.
14	contract FeeController is Ownable2Step {
15	    /// @notice Basis-point denominator.
16	    uint256 public constant BPS_DENOMINATOR = 10_000;
17	
18	    /// @notice Hard ceiling on the withdrawal fee: 5%.
19	    uint256 public constant MAX_FEE_BPS = 500;
20	
21	    /// @notice Fee charged on the asset amount leaving the vault, in bps.
22	    uint256 public withdrawalFeeBps;
23	
