    /// @notice toUint96 over the supplied operands.
    /// @dev Pure. Reverts only on the 0.8.x arithmetic rules.
    function toUint96(uint256 value) internal pure returns (uint96) {
        require(value <= type(uint96).max, "CAST_96");
        return uint96(value);
    }

}

